UPDATE rs_user_session SET last_active_at = GREATEST(last_active_at, #{now}), last_user_query = #{query}
WHERE session_id = #{sessionId} AND account_id = #{accountId} AND profile_user_id = #{profileUserId}
  AND status = 'ACTIVE' AND last_active_at > #{cutoff}

UPDATE rs_user_session SET last_active_at = GREATEST(last_active_at, #{now})
WHERE session_id = #{sessionId} AND account_id = #{accountId} AND profile_user_id = #{profileUserId}
  AND status = 'ACTIVE' AND last_active_at > #{cutoff}

UPDATE rs_user_session SET status = 'ENDED', end_reason = 'inactivity', ended_at = CURRENT_TIMESTAMP
WHERE session_id = #{sessionId} AND account_id = #{accountId} AND profile_user_id = #{profileUserId}
  AND status = 'ACTIVE' AND last_active_at <= #{cutoff}

