mapper.select:
SELECT session_id, account_id, profile_user_id, entry_scene,
       active_preferences_json, last_user_query, started_at, last_active_at, status
FROM rs_user_session
WHERE account_id = #{accountId} AND profile_user_id = #{profileUserId}
AND entry_scene = #{entryScene}
ORDER BY started_at DESC, session_id DESC
LIMIT #{limit}

SELECT session_id, account_id, profile_user_id, entry_scene,
       active_preferences_json, last_user_query, started_at, last_active_at, status
FROM rs_user_session
WHERE status = 'ACTIVE' AND last_active_at > #{cutoff} AND session_id > #{afterSessionId}
ORDER BY session_id LIMIT #{limit}
